const a = view(Inputs.range([0, 5], {label: "a (start radius)", value: 0, step: 0.1}))
const b = view(Inputs.range([0.1, 5], {label: "b (spacing per radian)", value: 1, step: 0.1}))
const turns = view(Inputs.range([1, 20], {label: "turns", value: 5, step: 1}))

Plot.plot({
  width: 520, height: 520, aspectRatio: 1, inset: 10,
  x: {axis: null}, y: {axis: null},
  marks: [Plot.line(d3.range(0, turns * 2 * Math.PI, 0.02).map(t => { const r = a + b * t; return [r * Math.cos(t), r * Math.sin(t)]; }), {strokeWidth: 2})]
})

const rows = (await FileAttachment("batches.csv").csv({typed: true})).map(d => ({
  ...d,
  purityFail: d.purity_pct < 99.0,
  moistFail: d.moisture_pct > 0.50,
  fail: d.purity_pct < 99.0 || d.moisture_pct > 0.50
}));
const fails = rows.filter(d => d.fail);
display(Plot.plot({
  title: "HPLC purity (limit ≥ 99.0 %)", x: {type: "point", label: "batch", tickRotate: -90}, y: {label: "purity %", domain: [98.4, 100]},
  marginBottom: 60, color: {domain: ["pass","fail"], range: ["steelblue","crimson"], legend: true},
  marks: [Plot.ruleY([99.0], {stroke: "crimson", strokeDasharray: "4"}),
    Plot.dot(rows, {x: "batch", y: "purity_pct", stroke: d => d.purityFail ? "fail" : "pass", r: d => d.purityFail ? 6 : 3}),
    Plot.text(rows.filter(d => d.purityFail), {x: "batch", y: "purity_pct", text: "batch", dy: -12})]
}));
display(Plot.plot({
  title: "Karl Fischer moisture (limit ≤ 0.50 %)", x: {type: "point", label: "batch", tickRotate: -90}, y: {label: "moisture %"},
  marginBottom: 60, color: {domain: ["pass","fail"], range: ["steelblue","crimson"], legend: true},
  marks: [Plot.ruleY([0.5], {stroke: "crimson", strokeDasharray: "4"}),
    Plot.dot(rows, {x: "batch", y: "moisture_pct", stroke: d => d.moistFail ? "fail" : "pass", r: d => d.moistFail ? 6 : 3}),
    Plot.text(rows.filter(d => d.moistFail), {x: "batch", y: "moisture_pct", text: "batch", dy: -12})]
}));
display(Inputs.table(fails.map(d => ({
  batch: d.batch, date: d.date, line: d.line, purity_pct: d.purity_pct, moisture_pct: d.moisture_pct,
  failed: [d.purityFail && "purity", d.moistFail && "moisture"].filter(Boolean).join(" + ")
}))));

