(() => {
  const r = rate / 100 / 12, n = years * 12;
  // M = P·r / (1 − (1+r)^−n)
  const m = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  const f = d3.format(",.2f");
  return htl.html`<div><b>Monthly payment: CHF ${f(m)}</b><br>
  Total paid: CHF ${f(m * n)} · interest: CHF ${f(m * n - principal)}<br>
  <small>M = P·r / (1 − (1+r)^−n), r = rate/12, n = years×12</small></div>`;
})()

(async () => {
  const rows = await FileAttachment("vendors.csv").csv({typed: true});
  const t = (wPrice + wSupport + wUptime) || 1;
  const scored = rows.map(r => ({vendor: r.vendor, score: (r.price*wPrice + r.support*wSupport + r.uptime*wUptime) / t}))
    .sort((a, b) => b.score - a.score);
  return htl.html`<div>${Inputs.table(scored.map(r => ({Vendor: r.vendor, Score: r.score.toFixed(2)})), {select: false})}
  <p>${scored[0].vendor} leads. Weights total ${t}% (normalised).</p></div>`;
})()

(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const key = d => (d.date instanceof Date ? d.date.toISOString() : String(d.date)).slice(0, 7);
  const m = d3.rollups(rows.filter(d => key(d).startsWith("2025")), v => d3.sum(v, d => d.revenue), key)
    .sort((a, b) => d3.ascending(a[0], b[0]))
    .map(([k, revenue]) => ({month: new Date(k + "-01T00:00:00Z"), revenue}));
  return Plot.plot({
    width: 800, height: 420, marginLeft: 60,
    title: "Monthly revenue, 2025",
    x: {type: "utc", tickFormat: "%b", label: null, interval: "month"},
    y: {label: "Revenue", grid: true, tickFormat: "s"},
    marks: [Plot.lineY(m, {x: "month", y: "revenue"}), Plot.dot(m, {x: "month", y: "revenue"}), Plot.ruleY([0])]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const r = 120, color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  return htl.html`<svg viewBox="${-r - 10} ${-r - 10} ${2 * r + 20} ${2 * r + 20}" width="320">
    ${arcs.map(a => htl.svg`<path d="${arc(a)}" fill="${color(a.data.task)}"/>
      <text transform="translate(${label.centroid(a)})" text-anchor="middle" fill="white" font-size="12">${a.data.task} ${a.data.value}%</text>`)}
  </svg>`;
}

